input.script:
export const meta = {
  name: 'jamf-pack-research',
  description: 'Research Jamf Pro API, DISA Jamf Pro STIG rules and Compliance Benchmarks API for a Maester pack',
  phases: [
    { title: 'Research', detail: 'API endpoints, STIG rules, benchmarks API' },
    { title: 'Verify', detail: 'fact-check each against primary docs' },
  ],
}

const CTX = `We are building a Maester Pack (PowerShell 7 checks run remotely, read-only) for Jamf Pro (cloud and on-prem). The connector authenticates with a Jamf Pro API client (OAuth2 client credentials, POST {server}/api/oauth/token with client_id, client_secret, grant_type=client_credentials) bound to a read-only API role. Use WebSearch/WebFetch (load via ToolSearch "select:WebSearch,WebFetch") against primary sources: developer.jamf.com (Jamf Pro API reference, Classic API reference, privileges reference), learn.jamf.com, public.cyber.mil / cyber.trackr.live / stigviewer for STIGs, github.com/usnistgov/macos_security. Do not rely on memory for endpoint paths or field names: open the reference page for each. Record the exact URL you used for every fact. Today is 2026-11-09.`

const TOPICS = [
  { key: 'pro-api', prompt: `For each tenant-hardening check below, give the exact Jamf Pro API endpoint (prefer the current Jamf Pro API /api/vN; use Classic /JSSResource only when no Jamf Pro API endpoint exists), HTTP method, the response JSON field names and types needed (with an abbreviated sample response), pagination/sort/filter parameters (RSQL), and the exact API role PRIVILEGE name(s) needed to read it (from Jamf's API privileges reference). Checks: (1) SSO settings: is SSO enabled, is it required for all users / is local login bypass allowed (GET /api/v3/sso or current); (2) API roles and their privileges (/api/v1/api-roles); (3) API integrations/clients: enabled, which roles, access token lifetime, and any last-used or created date if available (/api/v1/api-integrations); (4) Jamf Pro user accounts and groups: access level, privilege set (Administrator / Full access), enabled/disabled, last login if available, LDAP vs local (Classic /JSSResource/accounts or newer /api/v1/... account endpoints); (5) console password policy and lockout settings (account preferences / password policy endpoint, e.g. /api/v1/... "jamf-pro-account-preferences"? or Classic? find the real one); (6) Jamf Pro server version (/api/v1/jamf-pro-version) and how to know the latest supported release; (7) user-initiated enrollment settings (/api/v4/enrollment or current): is UIE enabled for computers and mobile devices, LDAP restriction; (8) Automated Device Enrollment instances and computer prestages (/api/v1/device-enrollments, /api/v3/computer-prestages): mandatory MDM profile, removable MDM profile, require authentication; (9) computer configuration profiles and their payloads/scope (Classic /JSSResource/osxconfigurationprofiles and /id/{id}; does the Jamf Pro API have one?), to find FileVault, Gatekeeper, firewall payloads scoped to all computers; (10) computer inventory with sections GENERAL, OPERATING_SYSTEM, DISK_ENCRYPTION, SECURITY (/api/v1/computers-inventory?section=...): lastContactTime, osVersion, FileVault status and personal recovery key escrow (individual key validity), SIP, Gatekeeper, firewall status, page-size limits; (11) mobile device inventory equivalents briefly; (12) audit/change management: is Change Management / log flushing or webhooks configured (any API?); (13) Jamf Pro "Jamf Pro server URL" and token invalidation (POST /api/v1/auth/invalidate-token or /api/oauth/... ). Also note any differences between Jamf Cloud and on-prem, and API rate limits.` },
  { key: 'stig', prompt: `Find the DISA Jamf Pro v10.x EMM STIG, latest version (expected V3R2, dated around 30 Sep 2026; verify the current version and release date). DISA STIGs are US Government works in the public domain. List EVERY rule: Vuln ID (V-xxxxxx), Rule ID (SV-...r..), STIG ID (JAMF-10-xxxxxx), severity (CAT I/II/III = high/medium/low), the rule title, a one-paragraph summary of the check text and fix text, and CCI / NIST 800-53 references if shown. For each rule judge whether a remote read-only check through the Jamf Pro API can verify it (yes / partial / no, and which endpoint/field), or whether it is a server OS, database, organisational or manual check. Also note the STIG's scope statement (is it about Jamf Pro managing iOS/iPadOS?).` },
  { key: 'benchmarks', prompt: `Research Jamf's Compliance Benchmarks API (Jamf Platform API, labelled Beta) and the NIST macOS Security Compliance Project (mSCP). Give: (1) base URL by region, token endpoint and request format, required scope, required headers (e.g. X-Environment-Id or similar), how a customer creates the platform API client credentials (Jamf Account / Platform API clients) and where the environment ID comes from; (2) every endpoint: list benchmarks/baselines, a benchmark's rules, per-rule stats (pass/fail counts), devices per rule, overall compliance percentage; exact paths, query params, pagination, and response field names with abbreviated samples; (3) requirements and limits (Jamf Pro version, Jamf Account SSO, cloud only, macOS only, which baselines: CIS L1/L2, NIST 800-53 low/moderate/high, STIG?); (4) the rule identifiers it returns: are they mSCP rule IDs (e.g. os_gatekeeper_enable)? Do results include CIS/STIG cross references? (5) mSCP: latest release name and date, repo layout of rules/*.yaml (fields: id, title, references.cis.benchmark, references.disa.disa_stig, references.nist.800-53r5, tags), licence. (6) The fallback: mSCP-generated compliance script writes results where (plist path, extension attribute "compliance" counts?) and what Jamf extension attribute names the mSCP guidance uses, so a connector can read failed-rule counts from computer inventory extension attributes. Also: does the Jamf Pro API itself (not the platform API) expose compliance benchmark results?` },
]

const results = await pipeline(
  TOPICS,
  t => agent(`${CTX}\n\nTask: ${t.prompt}\n\nReturn a thorough, structured Markdown report with source URLs next to each fact. Mark anything you could not confirm on a primary source as UNVERIFIED.`, { label: `research:${t.key}`, phase: 'Research' }),
  (r, t) => r ? agent(`${CTX}\n\nYou are a skeptical fact-checker. Here is a research report for topic "${t.key}":\n\n${r}\n\nOpen the primary sources and verify every endpoint path, HTTP method, field name, privilege name, rule ID, version and date. Correct anything wrong, fill gaps you can confirm, and mark the rest UNVERIFIED. Return the full corrected report in Markdown (not a diff), followed by a "Corrections" list.`, { label: `verify:${t.key}`, phase: 'Verify' }) : null,
)
return Object.fromEntries(TOPICS.map((t, i) => [t.key, results[i]]))

result.output:
function Test-MtPackScriptFile {
    <#
    .SYNOPSIS
    Checks one PowerShell file of a pack: function definitions only, then scans it for what it reaches.

    .DESCRIPTION
    Returns Functions (the names defined at the top level), Errors (Code, Message, Line) and Findings
    (Severity, Code, Message, Line).

    A file must not run code when it is loaded (section 4.3): no top-level statements, no script param
    block, no using statements, no class or enum definitions and no #Requires -Modules other than Maester.

    The scan reads the AST (section 9.6): dynamic code (Invoke-Expression, [scriptblock]::Create,
    Add-Type), process start and web requests to an address built at run time are Medium findings; .NET network
    classes (HttpClient, WebClient, WebRequest, sockets) are a High finding. A web request to a literal host that
    Uses.Network does not list (or with a user name before the host), a module import or install that
    Uses.Modules does not list, and, when Uses.TenantWrites is empty, a write through Invoke-MtGraphRequest or
    Invoke-MtAzureRequest (a write method, or one set at run time) or a Microsoft Graph command that changes
    the tenant (New-Mg*, Set-Mg*, Remove-Mg* and the like) are errors: undeclared reach.
    #>
    [CmdletBinding()]
    [OutputType([pscustomobject])]
    param(
        [Parameter(Mandatory)] [string] $Path,
        [Parameter()] [string[]] $DeclaredHost = @(),
        [Parameter()] [string[]] $DeclaredModule = @(),
        [Parameter()] [switch] $DeclaredWrites
    )

    $errors = [System.Collections.Generic.List[pscustomobject]]::new()
    $findings = [System.Collections.Generic.List[pscustomobject]]::new()
    $fail = { param($code, $message, $line) $errors.Add([pscustomobject]@{ Code = $code; Message = $message; Line = $line }) }
    $find = { param($severity, $code, $message, $line) $findings.Add([pscustomobject]@{ Severity = $severity; Code = $code; Message = $message; Line = $line }) }

    $tokens = $null
    $parseErrors = $null
    $ast = [System.Management.Automation.Language.Parser]::ParseFile($Path, [ref] $tokens, [ref] $parseErrors)
    if ($parseErrors) {
        foreach ($e in ($parseErrors | Select-Object -First 3)) { & $fail 'LoadFailed' "The file does not parse: $($e.Message)" $e.Extent.StartLineNumber }
        return [pscustomobject]@{ Functions = @(); Errors = $errors.ToArray(); Findings = $findings.ToArray() }
    }

    # Nothing may run when the file is loaded.
    if ($ast.ParamBlock) { & $fail 'CodeOnLoad' 'A pack file must not have a script-level param() block.' $ast.ParamBlock.Extent.StartLineNumber }
    foreach ($using in $ast.UsingStatements) { & $fail 'CodeOnLoad' "A pack file must not use '$($using.Extent.Text)': it runs when the file is loaded. Load libraries inside a function instead." $using.Extent.StartLineNumber }
    foreach ($block in @($ast.BeginBlock, $ast.ProcessBlock, $ast.DynamicParamBlock)) {
        if ($block -and $block.Statements.Count -gt 0) { & $fail 'CodeOnLoad' 'A pack file may contain only function definitions at the top level.' $block.Extent.StartLineNumber }
    }
    foreach ($statement in $ast.EndBlock.Statements) {
        if ($statement -is [System.Management.Automation.Language.TypeDefinitionAst]) { & $fail 'CodeOnLoad' "A pack file must not define the class or enum '$($statement.Name)': it is compiled when the file is loaded." $statement.Extent.StartLineNumber }
        elseif ($statement -isnot [System.Management.Automation.Language.FunctionDefinitionAst]) { & $fail 'CodeOnLoad' "A pack file may contain only function definitions at the top level; found '$($statement.Extent.Text.Split("`n")[0].Trim())'." $statement.Extent.StartLineNumber }
    }
    if ($ast.ScriptRequirements) {
        foreach ($m in $ast.ScriptRequirements.RequiredModules) {
            if ($m.Name -ne 'Maester') { & $fail 'CodeOnLoad' "A pack file must not use '#Requires -Modules $($m.Name)': it loads the module when the file is loaded. Declare it in Uses.Modules." 1 }
        }
        foreach ($a in $ast.ScriptRequirements.RequiredAssemblies) { & $fail 'CodeOnLoad' "A pack file must not use '#Requires -Assembly $a'." 1 }
    }
    $functions = @($ast.EndBlock.Statements | Where-Object { $_ -is [System.Management.Automation.Language.FunctionDefinitionAst] } | ForEach-Object { $_.Name })

    # The scan.
    $microsoftModules = '^(Microsoft\.Graph(\..+)?|Az(\..+)?|ExchangeOnlineManagement|MicrosoftTeams|PnP\.PowerShell|Microsoft\.Online\.SharePoint\.PowerShell|Maester|Pester|Microsoft\.PowerShell\..+)$'
    $hostAllowed = {
        param($name, $hosts)
        foreach ($h in $hosts) {
            if ($h.StartsWith('*.')) { if ($name.EndsWith($h.Substring(1), [System.StringComparison]::OrdinalIgnoreCase)) { return $true } }
            elseif ($h -eq $name) { return $true }
        }
        $false
    }
    $commands = $ast.FindAll({ param($n) $n -is [System.Management.Automation.Language.CommandAst] }, $true)
    foreach ($command in $commands) {
        $name = $command.GetCommandName()
        if (-not $name) { & $find 'Medium' 'DynamicCode' 'Calls a command whose name is computed at run time.' $command.Extent.StartLineNumber; continue }
        $line = $command.Extent.StartLineNumber
        $arguments = Get-MtPackCommandArgument -Command $command
        switch -Regex ($name) {
            '^(Invoke-Expression|iex)$' { & $find 'Medium' 'DynamicCode' 'Runs a string as code (Invoke-Expression).' $line }
            '^Add-Type$' { & $find 'Medium' 'DynamicCode' 'Compiles or loads code at run time (Add-Type).' $line }
            '^(Start-Process|saps|start)$' { & $find 'Medium' 'ProcessStart' 'Starts another process (Start-Process).' $line }
            '^(Invoke-RestMethod|irm|Invoke-WebRequest|iwr|curl|wget)$' {
                $uri = if ($arguments.Named.ContainsKey('Uri')) { $arguments.Named['Uri'] } elseif ($arguments.Positional.Count -gt 0) { $arguments.Positional[0] } else { $null }
                $literal = Get-MtPackLiteralString -Ast $uri
                # Read the host the way .NET does when it sends the request, not with a pattern.
                $parsed = $null
                if ($literal -and [uri]::TryCreate($literal, [System.UriKind]::Absolute, [ref] $parsed) -and $parsed.Scheme -in 'http', 'https') {
                    # A user name or password before the host ('REDACTED') hides where the request goes.
                    $authority = ($literal -replace '^[A-Za-z][A-Za-z0-9+.-]*://', '') -replace '[/?#\\].*$', ''
                    if ($parsed.UserInfo -or $authority.Contains('@')) { & $fail 'UndeclaredNetwork' "Sends a web request to an address with a user name or password before the host ($($parsed.Host)); Uses.Network cannot declare it." $line }
                    elseif (-not (& $hostAllowed $parsed.Host $DeclaredHost)) { & $fail 'UndeclaredNetwork' "Sends a web request to $($parsed.Host), which Uses.Network does not list." $line }
                } else { & $find 'Medium' 'DynamicUrl' 'Sends a web request to an address built at run time.' $line }
            }
            '^(Import-Module|ipmo|Install-Module|Install-PSResource|Save-Module|Save-PSResource|Install-Package)$' {
                $target = if ($arguments.Named.ContainsKey('Name')) { $arguments.Named['Name'] } elseif ($arguments.Positional.Count -gt 0) { $arguments.Positional[0] } else { $null }
                $module = Get-MtPackLiteralString -Ast $target
                if ($name -notmatch '^(Import-Module|ipmo)$') { & $fail 'UndeclaredModule' "Installs a module at run time ($name). Declare modules in Uses.Modules; Maester saves and checks them at install." $line }
                elseif (-not $module) { & $find 'Medium' 'DynamicCode' 'Imports a module whose name is computed at run time.' $line }
                elseif ($module -notmatch $microsoftModules -and -not ($DeclaredModule | Where-Object { $_ -eq $module }) -and $module -notmatch '[\\/]') {
                    & $fail 'UndeclaredModule' "Imports the module $module, which Uses.Modules does not list." $line
                }
            }
            '^(Invoke-MtGraphRequest|Invoke-MgGraphRequest|Invoke-MtAzureRequest|Invoke-AzRestMethod)$' {
                if ($DeclaredWrites) { break }
                $method = Get-MtPackLiteralString -Ast $(if ($arguments.Named.ContainsKey('Method')) { $arguments.Named['Method'] } else { $null })
                # Invoke-MgGraphRequest also takes the method by position.
                $verb = @($arguments.Positional | ForEach-Object { Get-MtPackLiteralString -Ast $_ } | Where-Object { $_ -match '^(POST|PATCH|PUT|DELETE)$' })
                if ($method -and $method -match '^(POST|PATCH|PUT|DELETE)$') {
                    & $fail 'UndeclaredTenantWrite' "Sends a $($method.ToUpperInvariant()) request through $name, a change to your tenant that Uses.TenantWrites does not declare." $line
                } elseif (-not $arguments.Named.ContainsKey('Method') -and $verb) {
                    & $fail 'UndeclaredTenantWrite' "Sends a $($verb[0].ToUpperInvariant()) request through $name, a change to your tenant that Uses.TenantWrites does not declare." $line
                } elseif (($arguments.Named.ContainsKey('Method') -and -not $method) -or @($command.CommandElements | Where-Object { $_ -is [System.Management.Automation.Language.VariableExpressionAst] -and $_.Splatted })) {
                    # A method built at run time, or passed in a splat, can be a write.
                    & $fail 'UndeclaredTenantWrite' "Sends a request through $name with a method that is set at run time, so it can change your tenant, and Uses.TenantWrites does not declare that." $line
                }
            }
            '^(?!Invoke-MgGraphRequest$)(New|Set|Update|Remove|Add|Invoke|Clear|Reset|Revoke|Restore|Confirm|Stop|Start)-Mg' {
                if (-not $DeclaredWrites) { & $fail 'UndeclaredTenantWrite' "Runs $name, a Microsoft Graph command that can change your tenant, which Uses.TenantWrites does not declare." $line }
            }
            '^New-Object$' {
                $type = if ($arguments.Named.ContainsKey('TypeName')) { $arguments.Named['TypeName'] } elseif ($arguments.Positional.Count -gt 0) { $arguments.Positional[0] } else { $null }
                if ($type -and -not (Get-MtPackLiteralString -Ast $type)) { & $find 'Medium' 'DynamicCode' 'Creates an object whose type is computed at run time (New-Object).' $line }
            }
        }
    }
    foreach ($member in $ast.FindAll({ param($n) $n -is [System.Management.Automation.Language.InvokeMemberExpressionAst] }, $true)) {
        $target = $member.Expression.Extent.Text
        $method = $member.Member.Extent.Text.Trim("'", '"')
        if ($target -match '^\[(System\.Management\.Automation\.)?scriptblock\]$' -and $method -eq 'Create') { & $find 'Medium' 'DynamicCode' 'Creates code from a string ([scriptblock]::Create).' $member.Extent.StartLineNumber }
        elseif ($target -match '^\[(System\.)?Diagnostics\.Process\]$' -and $method -eq 'Start') { & $find 'Medium' 'ProcessStart' 'Starts another process ([Diagnostics.Process]::Start).' $member.Extent.StartLineNumber }
        elseif ($target -match '^\[(System\.)?Reflection\.Assembly\]$' -and $method -match '^Load') { & $find 'Medium' 'DynamicCode' 'Loads an assembly at run time.' $member.Extent.StartLineNumber }

    # The folders and files the manifest names.
    foreach ($folder in @($manifest.Suites) + @($manifest.Helpers)) {
        if (-not (Test-Path -LiteralPath (Join-Path $root $folder) -PathType Container)) { & $fail 'InvalidManifest' "The folder '$folder' named in maester-pack.json does not exist." }
    }
    foreach ($c in $manifest.Connectors) {
        if ($c.File -and -not (Test-Path -LiteralPath (Join-Path $root $c.File) -PathType Leaf)) { & $fail 'InvalidManifest' "The connector file '$($c.File)' does not exist." }
    }

    # Every PowerShell file: function definitions only; names unique; then the scan.
    $functionFiles = @{}
    $declaredHosts = @($manifest.Uses.Network)
    $declaredModules = @(@($manifest.Uses.Modules) + @($manifest.Uses.UserModules) | ForEach-Object { [string]$_.Name })
    $declaredWrites = @($manifest.Uses.TenantWrites).Count -gt 0
    foreach ($f in ($digest.Files | Where-Object { $_.Path -match '\.ps(m?)1$' })) {
        $scan = Test-MtPackScriptFile -Path (Join-Path $root $f.Path) -DeclaredHost $declaredHosts -DeclaredModule $declaredModules -DeclaredWrites:$declaredWrites
        foreach ($e in $scan.Errors) { & $fail $e.Code "$($f.Path), line $($e.Line): $($e.Message)" }
        foreach ($finding in $scan.Findings) { & $find $finding.Severity $finding.Code $finding.Message $f.Path $finding.Line }
        foreach ($name in $scan.Functions) {
            $key = $name.ToLowerInvariant()
            if ($functionFiles.ContainsKey($key)) { & $fail 'DuplicateFunctionName' "The function $name is defined in both $($functionFiles[$key]) and $($f.Path). Function names must be unique within a pack." }
            else { $functionFiles[$key] = $f.Path }
        }
    }
    foreach ($c in $manifest.Connectors) {
        foreach ($fn in 'Connect', 'Test', 'Disconnect', 'Describe', 'Renew') {
            if ($c.PSObject.Properties[$fn] -and $c.$fn -and -not $functionFiles.ContainsKey(([string]$c.$fn).ToLowerInvariant())) {
                & $fail 'InvalidManifest' "The connector '$($c.Service)' names the function $($c.$fn), which the pack does not define."
            }
        }
    }
    foreach ($name in $manifest.Exports) {
        if (-not $functionFiles.ContainsKey($name.ToLowerInvariant())) { & $fail 'InvalidManifest' "Exports names the function $name, which the pack does not define." }
    }

    # Tests: the 3.0 rules, plus the pack rules.

