function Invoke-JamfHttp {
    <#
    .SYNOPSIS
    Sends one HTTPS request to a Jamf server. Every request of the pack goes through here.

    .DESCRIPTION
    The Jamf Pro server and the Jamf Platform API host differ for each customer, so the address is built at run
    time. Keeping the only Invoke-RestMethod call of the pack in this function keeps that in one place to review.
    It refuses anything but HTTPS, and anything but GET except the token requests the connectors send.

    Retries a 429 (rate limited) or 503 response up to three times, waiting as long as Retry-After asks (at most 30
    seconds) or two, four and eight seconds.
    #>
    [CmdletBinding()]
    [OutputType([object])]
    param(
        [Parameter(Mandatory)] [uri] $Uri,
        [Parameter()] [ValidateSet('GET', 'POST')] [string] $Method = 'GET',
        [Parameter()] [hashtable] $Headers = @{},
        [Parameter()] [object] $Body,
        [Parameter()] [string] $ContentType,
        # Only the connectors' token requests may POST.
        [Parameter()] [switch] $TokenRequest
    )

    if ($Uri.Scheme -ne 'https') { throw "The pack sends requests over HTTPS only, not to $($Uri.Scheme)://$($Uri.Host)." }
    if ($Method -eq 'POST' -and -not $TokenRequest) { throw 'The pack only reads from Jamf: it sends POST requests only to get or end a token.' }

    $request = @{
        Uri         = $Uri
        Method      = $Method
        Headers     = $Headers
        ErrorAction = 'Stop'
    }
    if ($PSBoundParameters.ContainsKey('Body')) { $request.Body = $Body }
    if ($ContentType) { $request.ContentType = $ContentType }

    $attempt = 0
    while ($true) {
        $attempt++
        try {
            return Invoke-RestMethod @request
        } catch {
            $status = [int]($_.Exception.Response.StatusCode)
            if ($status -notin 429, 503 -or $attempt -gt 3) { throw }
            $wait = [math]::Pow(2, $attempt)
            $retryAfter = $_.Exception.Response.Headers.RetryAfter
            if ($retryAfter -and $retryAfter.Delta) { $wait = [math]::Min(30, [math]::Ceiling($retryAfter.Delta.TotalSeconds)) }
            Write-Verbose "Jamf answered $status for $($Uri.AbsolutePath); trying again in $wait seconds."
            Start-Sleep -Seconds $wait
        }
    }
}

function ConvertTo-JamfServerUri {
    <#
    .SYNOPSIS
    Turns what the user typed for the Jamf Pro server into its HTTPS base address, ending in a slash.

    .EXAMPLE
    ConvertTo-JamfServerUri -Server contoso.jamfcloud.com

    Returns https://contoso.jamfcloud.com/.
    #>
    [CmdletBinding()]
    [OutputType([uri])]
    param([Parameter(Mandatory)] [string] $Server)

    $text = $Server.Trim()
    if ($text -notmatch '^[a-z][a-z0-9+.-]*://') { $text = "https://$text" }
    $parsed = $null
    if (-not [uri]::TryCreate($text, [System.UriKind]::Absolute, [ref] $parsed) -or -not $parsed.Host) {
        throw "'$Server' is not a Jamf Pro address. Use the address you open Jamf Pro at, such as https://contoso.jamfcloud.com."
    }
    if ($parsed.Scheme -ne 'https') { throw "Jamf Pro must be reached over HTTPS, not $($parsed.Scheme)." }
    if ($parsed.UserInfo) { throw 'Put the user name in Username, not in the server address.' }
    # Keep a path such as /jamf for a server behind a proxy, but drop what was typed after it.
    $path = $parsed.AbsolutePath.TrimEnd('/') -replace '/(api|JSSResource|index\.html).*$', ''
    [uri]"https://$($parsed.Authority)$path/"
}

function Update-JamfProToken {
    <#
    .SYNOPSIS
    Gets a Jamf Pro bearer token for the connection state and writes it, with its expiry, into the state.

    .DESCRIPTION
    An API client uses the client credentials grant (POST /api/oauth/token). A Jamf Pro account uses basic
    authentication once to get a token (POST /api/v1/auth/token). ExpiresOn tells Maester when to call the
    connector's Renew function.
    #>
    [CmdletBinding(SupportsShouldProcess)]
    param([Parameter(Mandatory)] [hashtable] $State)

    if (-not $PSCmdlet.ShouldProcess($State.Server.Host, 'Get a Jamf Pro token')) { return }

    if ($State.Method -eq 'ApiClient') {
        $response = Invoke-JamfHttp -Uri ([uri]::new($State.Server, 'api/oauth/token')) -Method POST -TokenRequest `
            -ContentType 'application/x-www-form-urlencoded' `
            -Body @{ client_id = $State.ClientId; client_secret = REDACTED; grant_type = 'client_credentials' }
        $State.Token = REDACTED
        $seconds = [int]$response.expires_in
        $State.ExpiresOn = [datetime]::UtcNow.AddSeconds([math]::Max(60, $seconds))
    } else {
        $pair = [Convert]::ToBase64String([Text.Encoding]::UTF8.GetBytes("$($State.Username):$($State.Password)"))
        $response = Invoke-JamfHttp -Uri ([uri]::new($State.Server, 'api/v1/auth/token')) -Method POST -TokenRequest `
            -Headers @{ Authorization = "Basic $pair"; Accept = 'application/json' }
        $State.Token = REDACTED
        $expires = [datetime]::MinValue
        $State.ExpiresOn = if ([datetime]::TryParse([string]$response.expires, [cultureinfo]::InvariantCulture,
                [System.Globalization.DateTimeStyles]::AdjustToUniversal, [ref] $expires)) { $expires } else { [datetime]::UtcNow.AddMinutes(20) }
    }
    if (-not $State.Token) { throw "Jamf Pro at $($State.Server.Host) did not return a token." }
}

function Invoke-JamfProRequest {
    <#
    .SYNOPSIS
    Reads one Jamf Pro API path through the connection, from the run's cache when it was read before.

    .DESCRIPTION
    A Maester run reports on one snapshot, so each path is read once per connection and kept in the connection's
    cache; several tests that read the same settings share one request. A 401 answer gets a new token once and
    tries again.

    Paths are relative to the server: 'api/v1/jamf-pro-version', or a Classic API path such as
    'JSSResource/accounts', which is asked for as JSON.

    .PARAMETER Path
    The path and query, relative to the Jamf Pro address.

    .PARAMETER NoCache
    Do not keep the answer, for a very large response that only one helper reads.
    #>
    [CmdletBinding()]
    [OutputType([object])]
    param(
        [Parameter(Mandatory)] [string] $Path,
        [Parameter()] [switch] $NoCache
    )

    $state = Get-MtConnectionState
    if (-not $state -or -not $state.Token) { throw 'Jamf Pro is not connected. Run Connect-Maester -Service JAMF.JamfPro.' }
    $key = $Path.TrimStart('/')
    if ($state.Cache.ContainsKey($key)) { return $state.Cache[$key] }

    $uri = [uri]::new($state.Server, $key)
    $send = { Invoke-JamfHttp -Uri $uri -Headers @{ Authorization = "Bearer $($state.Token)"; Accept = 'application/json' } }
    try {
        $response = & $send
    } catch {
        if ([int]($_.Exception.Response.StatusCode) -ne 401) { throw (New-JamfRequestError -ErrorRecord $_ -Path $key) }
        Update-JamfProToken -State $state
        try { $response = & $send } catch { throw (New-JamfRequestError -ErrorRecord $_ -Path $key) }
    }
    if (-not $NoCache) { $state.Cache[$key] = $response }
    $response
}

function New-JamfRequestError {
    <#
    .SYNOPSIS
    Turns a failed Jamf request into an error that says what to do, such as which privilege the API role lacks.
    #>
    [CmdletBinding()]
    [OutputType([System.Management.Automation.ErrorRecord])]
    param(
        [Parameter(Mandatory)] [System.Management.Automation.ErrorRecord] $ErrorRecord,
        [Parameter(Mandatory)] [string] $Path
    )

    $status = [int]($ErrorRecord.Exception.Response.StatusCode)
    $endpoint = ($Path -split '\?')[0]
    $message = switch ($status) {
        401 { "Jamf refused the token for $endpoint (401). Check the client ID and secret, and that the API client is enabled." }
        403 { "The API role cannot read $endpoint (403). Add the read privilege the pack's README lists for it to the API role." }
        404 { "Jamf has no $endpoint (404). The server may be older than the pack expects, or the feature is not licensed." }
        default { "Reading $endpoint from Jamf failed$(if ($status) { " ($status)" }): $($ErrorRecord.Exception.Message)" }
    }
    $exception = [System.InvalidOperationException]::new($message, $ErrorRecord.Exception)
    [System.Management.Automation.ErrorRecord]::new($exception, "JamfRequest$status", 'ConnectionError', $endpoint)
}

