# The release, for the framework's version: the release tag the checkout is on (release_27.1 gives 27.1), else the
# newest heading of the changelog, which on main can lag behind the release.
$version = $null
$tag = git -C $root describe --tags --exact-match 2>$null
if ($tag -match '^release_(\d+\.\d+)$') { $version = $Matches[1] }
$changelog = Join-Path $root 'CHANGELOG.md'
if (-not $version -and (Test-Path $changelog)) {
    $heading = Select-String -LiteralPath $changelog -Pattern 'Release\s+(\d+\.\d+)' | Select-Object -First 1
    if ($heading) { $version = $heading.Matches[0].Groups[1].Value }
}
if (-not $version) { throw 'Could not read the mSCP release. Check out a release tag: git clone --branch release_27.1 --depth 1 https://github.com/usnistgov/macos_security' }

