function Get-JamfProComputer {
    <#
    .SYNOPSIS
    Returns the inventory of every managed Mac, with the sections the fleet checks read.

    .DESCRIPTION
    Reads GET /api/v4/computers-inventory once per run with the GENERAL, OPERATING_SYSTEM, DISK_ENCRYPTION, SECURITY
    and EXTENSION_ATTRIBUTES sections, filtered to Macs that Jamf Pro manages. Falls back to /api/v3 on a server
    that has no v4. Needs the Read Computers privilege.
    #>
    [CmdletBinding()]
    [OutputType([object[]])]
    param()

    $query = 'section=GENERAL&section=OPERATING_SYSTEM&section=DISK_ENCRYPTION&section=SECURITY&section=EXTENSION_ATTRIBUTES&filter=general.remoteManagement.managed%3D%3Dtrue'
    try {
        Get-JamfProPagedResult -Path 'api/v4/computers-inventory' -Query $query
    } catch {
        if ($_.FullyQualifiedErrorId -notlike 'JamfRequest404*') { throw }
        Get-JamfProPagedResult -Path 'api/v3/computers-inventory' -Query $query
    }
}

function Get-JamfProAdministrator {
    <#
    .SYNOPSIS
    Returns the enabled Jamf Pro accounts and groups that hold full administrator rights.

    .DESCRIPTION
    An account or a group has full administrator rights when its privilege set is Administrator and its access is
    Full Access (not limited to a site). Each result has Kind (Account or Group), Name, Source (Local, Directory or
    Federated), Members (for a group) and the object itself. Needs Read Accounts and Read Account Groups.
    #>
    [CmdletBinding()]
    [OutputType([pscustomobject])]
    param()

    foreach ($account in (Get-JamfProPagedResult -Path 'api/v1/accounts' -Query 'filter=accountStatus%3D%3DEnabled')) {
        if ($account.privilegeLevel -eq 'ADMINISTRATOR' -and $account.accessLevel -eq 'FullAccess') {
            [pscustomobject]@{ Kind = 'Account'; Name = [string]$account.username; Source = Get-JamfProAccountSource -Account $account; Members = @(); Object = $account }
        }
    }
    foreach ($group in (Get-JamfProPagedResult -Path 'api/v1/account-groups')) {
        if ($group.privilegeLevel -eq 'ADMINISTRATOR' -and $group.accessLevel -eq 'FullAccess') {
            $source = if ([string]$group.ldapServerId -notin '', '-1') { 'Directory' } else { 'Local' }
            [pscustomobject]@{ Kind = 'Group'; Name = [string]$group.name; Source = $source; Members = @($group.members.username); Object = $group }
        }
    }
}

function Get-JamfProAccountSource {
    <#
    .SYNOPSIS
    Says where a Jamf Pro account signs in from: Local (a password kept by Jamf Pro), Directory (an LDAP or cloud
    identity provider account) or Federated (an SSO account).
    #>
    [CmdletBinding()]
    [OutputType([string])]
    param([Parameter(Mandatory)] [object] $Account)

    if ([string]$Account.accountType -eq 'FEDERATED') { return 'Federated' }
    if ([string]$Account.ldapServerId -notin '', '-1' -or $Account.distinguishedName) { return 'Directory' }
    'Local'
}

function Get-JamfProApiClient {
    <#
    .SYNOPSIS
    Returns the enabled Jamf Pro API clients, each with the privileges its API roles grant.

    .DESCRIPTION
    Joins GET /api/v1/api-integrations (Read API Integrations) to GET /api/v1/api-roles (Read API Roles) by role
    name. Each result has Name, ClientId, TokenLifetimeSeconds, Roles and Privileges. The API client the pack
    connects with is marked IsMaester.
    #>
    [CmdletBinding()]
    [OutputType([pscustomobject])]
    param()

    $roles = @{}
    foreach ($role in (Get-JamfProPagedResult -Path 'api/v1/api-roles')) { $roles[[string]$role.displayName] = @($role.privileges) }
    $own = [string](Get-MtConnectionState).ClientId

    foreach ($client in (Get-JamfProPagedResult -Path 'api/v1/api-integrations')) {
        if (-not $client.enabled) { continue }
        $names = @($client.authorizationScopes | Where-Object { $_ })
        $privileges = @($names | ForEach-Object { $roles[[string]$_] } | Where-Object { $_ } | Sort-Object -Unique)
        [pscustomobject]@{
            Name                 = [string]$client.displayName
            ClientId             = [string]$client.clientId
            TokenLifetimeSeconds = [int]$client.accessTokenLifetimeSeconds
            Roles                = $names
            Privileges           = $privileges
            IsMaester            = $own -and [string]$client.clientId -eq $own
        }
    }
}

function ConvertTo-JamfMarkdownTable {
    <#
    .SYNOPSIS
    Writes objects as a Markdown table, one column per property of the first object.

    .DESCRIPTION
    Escapes the pipe character and line breaks in values, so a name with a | in it cannot break the table, and
    joins arrays with commas.
    #>
    [CmdletBinding()]
    [OutputType([string])]
    param([Parameter(Mandatory)] [AllowEmptyCollection()] [object[]] $InputObject)

    if ($InputObject.Count -eq 0) { return '' }
    $columns = @($InputObject[0].PSObject.Properties.Name)
    $escape = {
        param($value)
        $text = if ($value -is [array]) { ($value | ForEach-Object { [string]$_ }) -join ', ' }
        elseif ($value -is [datetime]) { $value.ToUniversalTime().ToString('yyyy-MM-dd') }
        else { [string]$value }
        ($text -replace '\|', '\|' -replace '\r?\n', ' ').Trim()
    }
    $lines = [System.Collections.Generic.List[string]]::new()
    $lines.Add("| $($columns -join ' | ') |")
    $lines.Add("| $(($columns | ForEach-Object { '---' }) -join ' | ') |")
    foreach ($row in $InputObject) {
        $lines.Add("| $(($columns | ForEach-Object { & $escape $row.$_ }) -join ' | ') |")
    }
    $lines -join "`n"
}

function Update-JamfPlatformToken {
    <#
    .SYNOPSIS
    Gets a Jamf Platform API token for the connection state and writes it, with its expiry, into the state.

    .DESCRIPTION
    POST https://<region>.api.jamfcloud.com/auth/token with the client credentials grant. Tokens are tied to the
    region they were asked for and last 15 minutes, with no refresh token, so the pack asks for a new one.
    #>
    [CmdletBinding(SupportsShouldProcess)]
    param([Parameter(Mandatory)] [hashtable] $State)

    if (-not $PSCmdlet.ShouldProcess($State.Server.Host, 'Get a Jamf Platform API token')) { return }

    $response = Invoke-JamfHttp -Uri ([uri]::new($State.Server, 'auth/token')) -Method POST -TokenRequest `
        -ContentType 'application/x-www-form-urlencoded' `
        -Body @{ client_id = $State.ClientId; client_secret = REDACTED; grant_type = 'client_credentials' }
    $State.Token = REDACTED
    if (-not $State.Token) { throw "The Jamf Platform API at $($State.Server.Host) did not return a token." }
    $seconds = if ($response.expires_in) { [int]$response.expires_in } else { 900 }
    $State.ExpiresOn = [datetime]::UtcNow.AddSeconds([math]::Max(60, $seconds))
}

function Invoke-JamfPlatformRequest {
    <#
    .SYNOPSIS
    Reads one Jamf Platform API path through the connection, from the run's cache when it was read before.

    .DESCRIPTION
    Sends the X-Environment-Id header the Platform API needs on every request. A 401 answer gets a new token once
    and tries again.

    .PARAMETER Path
    The path and query, relative to the regional gateway, such as 'compliance-benchmarks/v1/benchmarks'.
    #>
    [CmdletBinding()]
    [OutputType([object])]
    param([Parameter(Mandatory)] [string] $Path)

    $state = Get-MtConnectionState -Service 'JAMF.Platform'
    if (-not $state -or -not $state.Token) { throw 'The Jamf Platform API is not connected. Run Connect-Maester -Service JAMF.Platform.' }
    $key = $Path.TrimStart('/')
    if ($state.Cache.ContainsKey($key)) { return $state.Cache[$key] }

    $uri = [uri]::new($state.Server, $key)
    $send = { Invoke-JamfHttp -Uri $uri -Headers @{ Authorization = "Bearer $($state.Token)"; 'X-Environment-Id' = $state.EnvironmentId; Accept = 'application/json' } }
    try {
        $response = & $send
    } catch {
        if ([int]($_.Exception.Response.StatusCode) -ne 401) { throw (New-JamfRequestError -ErrorRecord $_ -Path $key) }
        Update-JamfPlatformToken -State $state
        try { $response = & $send } catch { throw (New-JamfRequestError -ErrorRecord $_ -Path $key) }
    }
    $state.Cache[$key] = $response
    $response
}

