# Shared by the pack's Pester tests (spec/*.Tests.ps1). Dot-source it in BeforeAll.
#
# The pack reads Jamf through Invoke-JamfProRequest and Get-JamfProPagedResult, which answer from the connection's
# cache before they send anything. The tests fill that cache with recorded answers, so every check runs offline:
# a path that is not in the cache would go to https://fixture.invalid and fail.
#
# A plain path is the answer of Invoke-JamfProRequest; 'paged:<path>?<query>' is the array of results of
# Get-JamfProPagedResult, with the query exactly as the helper builds it.

$script:PackRoot = (Resolve-Path "$PSScriptRoot/..").Path

function Import-JamfSpecMaester {
    $maester = if ($env:MAESTER_MODULE) { $env:MAESTER_MODULE } else { 'Maester' }
    Import-Module $maester -Force -WarningAction SilentlyContinue
    # Loading the pack once registers its services, so the tests can set their connection state.
    $null = Invoke-MtTest -Path $script:PackRoot -Id MP.JAMF.1001 -WarningAction SilentlyContinue
}

function Get-JamfSpecQuery {
    # The queries the pack's helpers send, so fixtures and helpers cannot drift apart.
    param([ValidateSet('Computers', 'MobileDevices', 'Accounts')] [string] $Name)
    switch ($Name) {
        'Computers' { 'paged:api/v4/computers-inventory?section=GENERAL&section=OPERATING_SYSTEM&section=DISK_ENCRYPTION&section=SECURITY&section=EXTENSION_ATTRIBUTES&filter=general.remoteManagement.managed%3D%3Dtrue' }
        'MobileDevices' { 'paged:api/v2/mobile-devices/detail?section=GENERAL&section=SECURITY&exception-handling=LENIENT&filter=managed%3D%3Dtrue' }
        'Accounts' { 'paged:api/v1/accounts?filter=accountStatus%3D%3DEnabled' }
    }
}

function Set-JamfSpecConnection {
    <#
    Connects the pack to recorded answers. -Cache maps paths to answers; hashtables are turned into objects, as
    Invoke-RestMethod returns them.
    #>
    param(
        [hashtable] $Cache = @{},
        [hashtable] $Platform
    )
    $toObject = {
        param($value)
        ($value | ConvertTo-Json -Depth 20 | ConvertFrom-Json -Depth 20)
    }
    $pro = @{}
    foreach ($key in $Cache.Keys) {
        $value = & $toObject $Cache[$key]
        if ($key -like 'paged:*') { $value = @($value) }
        $pro[$key] = $value
    }
    Set-MtConnectionState -Service JAMF.JamfPro -Value @{ Server = [uri]'https://fixture.invalid/'; Token = 'fixture'; ClientId = 'maester-client'; Method = 'ApiClient'; Cache = $pro } -Tenant 'fixture.invalid'
    if ($Platform) {
        $p = @{}
        foreach ($key in $Platform.Keys) { $p[$key] = & $toObject $Platform[$key] }
        Set-MtConnectionState -Service JAMF.Platform -Value @{ Server = [uri]'https://fixture.invalid/'; Token = 'fixture'; EnvironmentId = '00000000-0000-0000-0000-000000000000'; Cache = $p } -Tenant 'fixture'
    } elseif (Get-MtConnectionState -Service JAMF.Platform) {
        Clear-MtConnectionState -Service JAMF.Platform
    }
}

function Invoke-JamfSpecTest {
    <# Runs one test (or family) of the pack against the recorded answers and returns its rows. #>
    param(
        [Parameter(Mandatory)] [string] $Id,
        [hashtable] $Cache = @{},
        [hashtable] $Platform,
        [hashtable] $Parameter
    )
    Set-JamfSpecConnection -Cache $Cache -Platform $Platform
    $run = @{ Path = $script:PackRoot; Id = $Id }
    if ($Parameter) { $run.Parameter = $Parameter }
    @(Invoke-MtTest @run)
}

function New-JamfSpecMac {
    <# One managed Mac in the shape GET /api/v4/computers-inventory returns. Override any section with -Set. #>
    param(
        [string] $Name = 'Mac-01',
        [hashtable] $General = @{},
        [hashtable] $OperatingSystem = @{},
        [hashtable] $DiskEncryption = @{},
        [hashtable] $Security = @{},
        [object[]] $ExtensionAttributes = @()
    )
    $merge = {
        param([hashtable] $base, [hashtable] $over)
        foreach ($k in $over.Keys) { $base[$k] = $over[$k] }
        $base
    }
    @{
        id                  = [guid]::NewGuid().ToString()
        general             = & $merge @{ name = $Name; lastContact = [datetime]::UtcNow.AddDays(-1).ToString('o'); remoteManagement = @{ managed = $true } } $General
        operatingSystem     = & $merge @{ name = 'macOS'; version = '26.1'; fileVault2Status = 'ALL_ENCRYPTED' } $OperatingSystem
        diskEncryption      = & $merge @{ fileVault2Enabled = $true; individualRecoveryKeyValidityStatus = 'VALID' } $DiskEncryption
        security            = & $merge @{ sipStatus = 'ENABLED'; gatekeeperStatus = 'APP_STORE_AND_IDENTIFIED_DEVELOPERS'; firewallEnabled = $true } $Security
        extensionAttributes = $ExtensionAttributes
    }
}

function New-JamfSpecMobileDevice {
    <# One managed iPhone or iPad in the shape GET /api/v2/mobile-devices/detail returns. #>
    param(
        [string] $Name = 'iPhone-01',
        [hashtable] $General = @{},
        [hashtable] $Security = @{}
    )
    $g = @{ displayName = $Name; osVersion = '26.1'; managed = $true; supervised = $true; lastInventoryUpdateDate = [datetime]::UtcNow.AddDays(-1).ToString('o') }
    foreach ($k in $General.Keys) { $g[$k] = $General[$k] }
    $s = @{ passcodePresent = $true; passcodeCompliant = $true; passcodeCompliantWithProfile = $true; jailBreakDetected = $false; dataProtected = $true }
    foreach ($k in $Security.Keys) { $s[$k] = $Security[$k] }
    @{ mobileDeviceId = [guid]::NewGuid().ToString(); displayName = $Name; general = $g; security = $s }
}

# Unit tests of the pack, run with Pester against an installed Maester (see .github/workflows/check-pack.yml):
#   Invoke-Pester ./spec
# Set MAESTER_MODULE to a Maester.psd1 to test against a checkout of Maester instead.
Describe 'Jamf Pro pack' {
    BeforeAll {
        . "$PSScriptRoot/Fixture.ps1"
        Import-JamfSpecMaester
    }

    Context 'the pack files' {
        It 'has valid native tests, each with its guide' {
            $files = Get-ChildItem -LiteralPath (Join-Path $script:PackRoot 'tests') -Filter 'Test.*.ps1'
            $files.Count | Should -BeGreaterThan 0
            foreach ($file in $files) {
                $test = Get-MtTest -Path $file.FullName
                $test.Errors | Should -BeNullOrEmpty -Because $file.Name
                $test.IsValid | Should -BeTrue -Because $file.Name
                Test-Path ($file.FullName -replace '\.ps1$', '.md') | Should -BeTrue -Because "$($file.Name) needs its guide"
            }
        }

        It 'maps every Control of a framework the pack declares to a requirement in its file' {
            $frameworks = @{}
            foreach ($file in Get-ChildItem (Join-Path $script:PackRoot 'tests/frameworks') -Filter '*.json') {
                $f = Get-Content $file.FullName -Raw | ConvertFrom-Json
                $frameworks[$f.Framework] = @($f.Requirements.Id)
            }
            foreach ($file in Get-ChildItem (Join-Path $script:PackRoot 'tests') -Filter 'Test.*.ps1') {
                $text = Get-Content $file.FullName -Raw
                foreach ($m in [regex]::Matches($text, "'((disa-jamf-pro-stig|mscp):([^']+))'")) {
                    $frameworks[$m.Groups[2].Value] | Should -Contain $m.Groups[3].Value -Because "$($file.Name) names $($m.Groups[1].Value)"
                }
            }
        }

        It 'passes the content checks Install-MtPack runs, at Medium risk at most' {
            $check = Test-MtPack $script:PackRoot -Official
            @($check.Errors | Where-Object { $_.Message -notmatch '^(build|spec)/' }) | Should -BeNullOrEmpty
            $check.Risk | Should -BeIn 'Low', 'Medium'
        }
    }

    Context 'MP.JAMF.1001 single sign-on' {
        It 'passes when SSO is on' {
            $row = Invoke-JamfSpecTest -Id MP.JAMF.1001 -Cache @{ 'api/v3/sso' = @{ ssoEnabled = $true; configurationType = 'SAML'; samlSettings = @{ idpProviderType = 'AZURE' } } }
            $row.Result | Should -Be 'Passed'
            $row.Benchmark.Requirement | Should -Be 'V-241796'
        }

        It 'fails when SSO is off' {
            (Invoke-JamfSpecTest -Id MP.JAMF.1001 -Cache @{ 'api/v3/sso' = @{ ssoEnabled = $false } }).Result | Should -Be 'Failed'
        }
    }

    Context 'MP.JAMF.1018 FileVault' {
        It 'passes when enough Macs are encrypted and lists the others' {
            $macs = @(1..19 | ForEach-Object { New-JamfSpecMac -Name "Mac-$_" }) + (New-JamfSpecMac -Name 'Plain' -OperatingSystem @{ fileVault2Status = 'NOT_ENCRYPTED' })
            $row = Invoke-JamfSpecTest -Id MP.JAMF.1018 -Cache @{ (Get-JamfSpecQuery Computers) = $macs }
            $row.Result | Should -Be 'Passed'
            $row.ResultDetail.TestResult | Should -Match 'Plain'
        }

        It 'fails below the minimum share' {
            $macs = @((New-JamfSpecMac), (New-JamfSpecMac -Name 'Plain' -OperatingSystem @{ fileVault2Status = 'NOT_ENCRYPTED' }))
            (Invoke-JamfSpecTest -Id MP.JAMF.1018 -Cache @{ (Get-JamfSpecQuery Computers) = $macs }).Result | Should -Be 'Failed'
        }

        It 'takes the share from the MinimumPercent parameter' {
            $macs = @((New-JamfSpecMac), (New-JamfSpecMac -Name 'Plain' -OperatingSystem @{ fileVault2Status = 'NOT_ENCRYPTED' }))
            (Invoke-JamfSpecTest -Id MP.JAMF.1018 -Cache @{ (Get-JamfSpecQuery Computers) = $macs } -Parameter @{ MinimumPercent = 50 }).Result | Should -Be 'Passed'
        }

        It 'is skipped when no Mac is managed' {
            (Invoke-JamfSpecTest -Id MP.JAMF.1018 -Cache @{ (Get-JamfSpecQuery Computers) = @() }).Result | Should -Be 'Skipped'
        }
    }
}

{
  "$schema": "https://maester.dev/schemas/maester-pack-guide-1.0.json",
  "Summary": "Checks a Jamf Pro server's security settings (single sign-on, administrators, API clients, enrollment) and the security of the Macs, iPhones and iPads it manages, mapped to the DISA Jamf Pro STIG and the NIST macOS Security Compliance Project.",
  "Prerequisites": [
    { "Text": "Install the pack once.", "Command": "Install-MtPack maester365/maester-pack-jamf" },
    { "Text": "Jamf Pro 10.49 or later (Jamf Cloud or on-premises), and a Jamf Pro administrator who can create an API role and client." },
    { "Text": "Optional, for the Compliance Benchmarks results: Jamf Cloud with Jamf Pro 11.16 or later, at least one benchmark, and a Jamf Account administrator who can create an integration." },
    { "Text": "PowerShell 7.4 or later and Maester 3.0 or later." }
  ],
  "Connect": {
    "Steps": [
      { "Text": "In Jamf Pro, go to Settings > System > API roles and clients. Create an API role named Maester (read only) with the Read privileges listed in the pack's README, then create an API client with that role, enable it and generate a client secret." },
      { "Text": "Keep the secret in an environment variable, then connect.", "Command": "$env:MAESTER_JAMF_JAMFPRO_CLIENTSECRET = 'REDACTED'\nConnect-Maester -Service JAMF.JamfPro -ServiceSetting @{ Server = 'https://contoso.jamfcloud.com'; ClientId = '<client id>' }" },
      { "Text": "Optional: for the Compliance Benchmarks results, create an integration in Jamf Account scoped to your Jamf Pro environment with only the compliance-benchmarks:read scope, then connect to it.", "Command": "$env:MAESTER_JAMF_PLATFORM_CLIENTSECRET = 'REDACTED'\nConnect-Maester -Service JAMF.Platform -ServiceSetting @{ Region = 'us'; ClientId = '<client id>'; EnvironmentId = '<environment id>' }" }
    ],
    "Notes": [
      "The pack only reads. Its only POST requests get or end a token.",
      "Settings can also go in maester-config.json under Connections.JAMF.JamfPro and Connections.JAMF.Platform. Keep secrets in environment variables, not in the file.",
      "The Compliance Benchmarks check runs only when JAMF.Platform is connected."
    ],
    "More": "https://github.com/maester365/maester-pack-jamf#connect"
  },
  "Run": {
    "Commands": [
      { "Text": "Only the Jamf Pro checks", "Command": "Invoke-Maester -Pack JAMF -SkipBuiltIn" },
      { "Text": "Maester's checks and the Jamf Pro checks", "Command": "Invoke-Maester -Pack JAMF" }
    ],
    "Notes": [
      "Thresholds, such as the share of Macs that must have FileVault on, are test parameters. Set them per test under TestSettings in maester-config.json."
    ],
    "More": "https://github.com/maester365/maester-pack-jamf#settings"
  },
  "AppOnly": {
    "Supported": true,
    "Methods": { "Certificate": false, "ClientSecret": true, "ManagedIdentity": false, "WorkloadIdentity": false },
    "Text": "The pack always signs in as a Jamf Pro API client with a client secret, so it runs unattended in a pipeline. Pass the client ID and secret through environment variables.",
    "Command": "$env:MAESTER_JAMF_JAMFPRO_SERVER = 'https://contoso.jamfcloud.com'\n$env:MAESTER_JAMF_JAMFPRO_CLIENTID = '<client id>'\n$env:MAESTER_JAMF_JAMFPRO_CLIENTSECRET = 'REDACTED'\nInvoke-Maester -Pack JAMF -SkipBuiltIn -NonInteractive",
    "More": "https://github.com/maester365/maester-pack-jamf#run-it-in-a-pipeline"
  },
  "Links": [
    { "Text": "Jamf Pro API roles and clients", "Url": "https://learn.jamf.com/r/en-US/jamf-pro-documentation-current/API_Roles_and_Clients" },
    { "Text": "NIST macOS Security Compliance Project", "Url": "https://github.com/usnistgov/macos_security" },
    { "Text": "DISA STIG library", "Url": "https://public.cyber.mil/stigs/downloads/" }
  ],
  "Support": {
    "Pack": "https://github.com/maester365/maester-pack-jamf/issues"
  }
}

